'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var PI = require( '@stdlib/constants/float64/pi' );


// MAIN //

/**
* Returns the differential entropy of a half-normal distribution with scale parameter `sigma`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} differential entropy
*
* @example
* var y = entropy( 1.0 );
* // returns 0.7257913526447274
*
* @example
* var y = entropy( 4.0 );
* // returns 2.112085713764618
*
* @example
* var y = entropy( NaN );
* // returns NaN
*
* @example
* var y = entropy( -1.0 );
* // returns NaN
*/
function entropy( sigma ) {
	if ( isnan( sigma ) || sigma < 0.0 ) {
		return NaN;
	}
	if ( sigma === 0.0 ) {
		return -Infinity;
	}
	// Entropy = 0.5 * ln(PI * sigma^2 / 2) + 0.5
	return ( 0.5 * ln( ( PI * sigma * sigma ) / 2.0 ) ) + 0.5;
}


// EXPORTS //

module.exports = entropy;
